from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import outage_refund
from ledgerly.models import Payment
from ledgerly.errors import BillingError

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def mk(amt="80.00", status="captured"):
    return Payment("p","i",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# partial then full
p=mk(); outage_refund(p,Decimal("30.00"),T0); assert p.refunded_amount==Decimal("30.00") and p.status=="captured"
outage_refund(p,Decimal("50.00"),T0); assert p.refunded_amount==Decimal("80.00") and p.status=="refunded"
print("partial/full ok")

# over refund
p=mk()
try: outage_refund(p,Decimal("80.01"),T0); print("FAIL")
except BillingError as e: print("over:",e.code)

# non-positive
for a in ("0","-1"):
    try: outage_refund(mk(),Decimal(a),T0); print("FAIL")
    except BillingError as e: print("nonpos:",e.code)

# not captured
try: outage_refund(mk(status="authorized"),Decimal("1"),T0); print("FAIL")
except BillingError as e: print("state:",e.code)

# approval threshold
try: outage_refund(mk("2000.00"),Decimal("1000.01"),T0); print("FAIL")
except BillingError as e: print("approval:",e.code)
p=mk("2000.00"); outage_refund(p,Decimal("1000.00"),T0); print("at threshold ok")
p=mk("2000.00"); outage_refund(p,Decimal("1000.01"),T0,approved_by="mgr"); print("approved ok")

# idempotency
audit.clear()
p=mk(); r1=outage_refund(p,Decimal("10.00"),T0,idempotency_key="k1")
r2=outage_refund(p,Decimal("10.00"),T0,idempotency_key="k1")
assert r1 is r2 and p.refunded_amount==Decimal("10.00")
print("idempotent ok")

# float rejected
try: outage_refund(mk(),1.5,T0); print("FAIL")
except BillingError as e: print("float:",e.code)
EOF"}

